{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, a close structural analog sharing the dimethoxy-substituted tetrahydroisoquinoline/benzoquinolizine core, has very low absolute oral bioavailability (mean 4.9 ± 3.2%) in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Individual tetrabenazine absolute oral bioavailability values are consistently below 10% (e.g., 8.5%, 7.4%, 5.3%, 1.3%, 2.0%, 0.5%, 0.1%), supporting extensive first-pass metabolism and F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a tetrabenazine prodrug, has about 49% absolute oral bioavailability, but this reflects prodrug masking of first-pass metabolism and is less transferable to the non-prodrug query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a non-prodrug tetrabenazine-like dimethoxyisoquinoline/benzazepinone; the closest structural and mechanistic evidence from tetrabenazine shows consistently very low absolute oral bioavailability (<10%), supporting F < 20%.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "The exact pharmacological target and metabolic clearance of the query are not established from the provided evidence.",
    "Valbenazine's higher F is prodrug-related and may not apply to the non-prodrug query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C38"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tetrabenazine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C29"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "valbenazine"
    }
  ],
  "revision_action": "initial"
}

